audit('zakharovmikhailov1978relativistic','https://zakharov75.itp.ac.ru/static/local/zve75/zakharov/1978/1978-03-e_047_06_1017.pdf','read the result','Introduction; sections 1--3 and sphere reduction in section 3; scope of section 6','Full primary author-archive PDF opened (turn106view1, turn145view1, turn146view1). The sphere attribution, projector reduction, distinction between Grassmann and general Stiefel spaces, and the section 6 scope were read. Submitted 4 January 1978; Russian issue June 1978; English page carries 1979 copyright.')
for a in references:
    if a['key']=='krichever1978rational':
        a['opened_url_evidence']='Primary author PDF opened, downloaded and all three pages rendered and inspected. Received 6 September 1977; published in volume 12(1), 1978. Notebook normalization is tested directly; the published Hamiltonian is not called false without fixing its time and Poisson conventions.'
    # Spacing in older audit checkpoints; preserve exact URLs and reference IDs.
    a['locator']=re.sub(r'(?<=[A-Za-z])(?=\d)', ' ', a['locator'])
    a['locator']=a['locator'].replace('Theorems1','Theorems 1').replace('section4','section 4').replace('pp160','pp.160').replace('pp2662','pp.2662').replace('FullURL','Full URL')
save()

